package main

import (
	"fmt"
	"os"
	"strings"
)

// countWords returns the number of whitespace-separated words in s.
func countWords(s string) int {
	n := 0
	inWord := false
	for _, r := range s {
		if r == ' ' || r == '\n' || r == '\t' {
			if inWord {
				n++
			}
			inWord = false
			continue
		}
		inWord = true
	}
	return n
}

func main() {
	text := "the quick brown fox jumps over the lazy dog"
	if len(os.Args) > 1 {
		text = strings.Join(os.Args[1:], " ")
	}
	fmt.Println(countWords(text))
}

